@orders_bp.route("/paged", methods=["GET"])
@require_role("manager")
def paged_orders():
    """List orders with limit/offset pagination."""
    limit = request.args.get("limit", "20")
    offset = request.args.get("offset", "0")
    session = get_session()
    rows = session.execute(
        text(f"SELECT id, user_id, status, total FROM orders LIMIT {limit} OFFSET {offset}")
    )
    return jsonify([dict(r._mapping) for r in rows])

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)
        return wrapper
    return decorator
